<script setup lang="ts">
import {starterModels} from '../../../shared/patterns'
usePageMeta('纸上学堂','阅读有来源的剪纸故事、技法与原创纹样练习，了解纸面与留白。')
const route=useRoute(),q=ref(String(route.query.q||'')),search=ref(q.value),category=ref(String(route.query.category||''))
const {data,pending,error,refresh}=await useFetch<any[]>('/api/articles',{query:{q:search,category}})
function find(){search.value=q.value;navigateTo({path:'/learn',query:{...(q.value?{q:q.value}:{}),...(category.value?{category:category.value}:{})}},{replace:true})}
</script>
<template><div class="wrap page"><Breadcrumbs :items="[{label:'纸上学堂'}]"/><header class="page-heading"><p class="eyebrow">READ THE PAPER</p><h1>纸薄，故事很长。</h1><p>读懂一处留白，再剪下一片自己的风景。</p></header><div class="filter-bar"><div class="filter-tabs" aria-label="文章分类"><button v-for="c in ['','纸上故事','技法入门','纹样观察','创作手记']" :key="c" :class="{selected:category===c}" @click="category=c;find()">{{c||'全部札记'}}</button></div><form class="search-form" @submit.prevent="find"><label for="article-search" class="sr-only">搜索知识</label><input id="article-search" v-model="q" maxlength="80" placeholder="找一个故事或纹样" type="search"/><button aria-label="搜索知识">搜索 ↗</button></form></div><AsyncState :pending="pending" :error="error" :empty="!data?.length" @retry="refresh"><div class="story-grid knowledge-grid"><NuxtLink v-for="(a,i) in data" :key="a.id" :to="`/learn/${a.slug}`" class="story-card"><div class="story-illustration" :class="`illustration-${i%3}`"><PaperArt :model="starterModels[(i+1)%8]!" :label="a.title+'原创数字插图'"/><span class="illustration-label">{{a.category}}</span></div><div class="story-meta"><span>{{a.category}}</span><span>札记 / 0{{i+1}}</span></div><h2>{{a.title}}</h2><p>{{a.summary}}</p><span class="text-link">翻开这一页 →</span></NuxtLink></div></AsyncState></div></template>
